/**
 * Component: UserProfilePanel (TopNavigation)
 *
 * Side drawer panel for user profile menu (Phase 2.31)
 *
 * Features:
 * - Right-side Material-UI Drawer (360px wide)
 * - Menu items: History, Saved Properties, Comparisons
 * - Sticky bottom section: Account Settings, Sign Out, Version code
 * - Smooth slide-in animation (300ms)
 * - Mobile responsive: 90% viewport width on small screens
 * - WCAG AA accessibility compliance
 * - Click outside to close
 *
 * Design Tokens (Style4-V2):
 * - Drawer width: 360px (desktop), 90vw (mobile <600px)
 * - Background: #ffffff
 * - Menu item: 14px/500, color #0b2d2c
 * - Hover: background #f5f5f5
 * - Divider: #e0e0e0
 * - Icons: 20px, color #0b2d2c
 * - Version text: 12px/400, color #999999
 */

import React, { useCallback } from 'react';
import {
  Drawer,
  Box,
  List,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Divider,
  Typography,
  Button,
  useMediaQuery,
  useTheme,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
} from '@mui/material';
import HistoryIcon from '@mui/icons-material/History';
import BookmarkIcon from '@mui/icons-material/Bookmark';
import CompareArrowsIcon from '@mui/icons-material/CompareArrows';
import SettingsIcon from '@mui/icons-material/Settings';
import LogoutIcon from '@mui/icons-material/Logout';
import PaletteIcon from '@mui/icons-material/Palette';
import { useAppDispatch, useAppSelector } from '../../../../store';
import { setTheme, selectCurrentTheme, type ThemeType } from '../../../../store/slices/themeSlice';

interface UserProfilePanelProps {
  open: boolean;
  onClose: () => void;
  onMenuItemClick: (item: 'history' | 'saved' | 'comparisons' | 'settings' | 'signout') => void;
  versionCode?: string;
}

interface MenuItem {
  id: 'history' | 'saved' | 'comparisons' | 'settings' | 'signout';
  label: string;
  icon: React.ReactNode;
  action: () => void;
  isBottom?: boolean;
  isDanger?: boolean;
}

/**
 * User Profile Panel Drawer Component
 *
 * Displays user menu with navigation items and account settings
 */
export const UserProfilePanel: React.FC<UserProfilePanelProps> = ({
  open,
  onClose,
  onMenuItemClick,
  versionCode = 'v2.31.0',
}) => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const dispatch = useAppDispatch();
  const currentTheme = useAppSelector(selectCurrentTheme);

  /**
   * Handle theme change
   */
  const handleThemeChange = useCallback(
    (event: any) => {
      const newTheme = event.target.value as ThemeType;
      dispatch(setTheme(newTheme));
    },
    [dispatch]
  );

  /**
   * Handle menu item click
   */
  const handleMenuItemClick = useCallback(
    (itemId: MenuItem['id']) => {
      onMenuItemClick(itemId);
    },
    [onMenuItemClick]
  );

  /**
   * Menu items configuration
   */
  const menuItems: MenuItem[] = [
    {
      id: 'history',
      label: 'History',
      icon: <HistoryIcon sx={{ fontSize: '20px', color: '#0b2d2c' }} />,
      action: () => handleMenuItemClick('history'),
      isBottom: false,
    },
    {
      id: 'saved',
      label: 'Saved Properties',
      icon: <BookmarkIcon sx={{ fontSize: '20px', color: '#0b2d2c' }} />,
      action: () => handleMenuItemClick('saved'),
      isBottom: false,
    },
    {
      id: 'comparisons',
      label: 'Comparisons',
      icon: <CompareArrowsIcon sx={{ fontSize: '20px', color: '#0b2d2c' }} />,
      action: () => handleMenuItemClick('comparisons'),
      isBottom: false,
    },
    {
      id: 'settings',
      label: 'Account Settings',
      icon: <SettingsIcon sx={{ fontSize: '20px', color: '#0b2d2c' }} />,
      action: () => handleMenuItemClick('settings'),
      isBottom: true,
    },
    {
      id: 'signout',
      label: 'Sign Out',
      icon: <LogoutIcon sx={{ fontSize: '20px', color: '#d32f2f' }} />,
      action: () => handleMenuItemClick('signout'),
      isBottom: true,
      isDanger: true,
    },
  ];

  // Separate menu items into top and bottom sections
  const topMenuItems = menuItems.filter((item) => !item.isBottom);
  const bottomMenuItems = menuItems.filter((item) => item.isBottom);

  return (
    <Drawer
      open={open}
      onClose={onClose}
      anchor="right"
      aria-label="User profile menu"
      sx={{
        '& .MuiDrawer-paper': {
          width: isMobile ? '90vw' : '360px',
          maxWidth: 'calc(100vw - 32px)',
          backgroundColor: '#ffffff',
          borderLeft: '1px solid #e0e0e0',
          boxShadow: 'none',
        },
      }}
    >
      {/* Drawer Content */}
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          height: '100%',
          backgroundColor: '#ffffff',
        }}
      >
        {/* Top Menu Items */}
        <List
          sx={{
            flex: 1,
            padding: 0,
            overflow: 'auto',
          }}
        >
          {topMenuItems.map((item, index) => (
            <ListItem
              key={item.id}
              disablePadding
              sx={{
                borderBottom: index < topMenuItems.length - 1 ? 'none' : '1px solid #e0e0e0',
              }}
            >
              <ListItemButton
                onClick={item.action}
                aria-label={item.label}
                sx={{
                  paddingLeft: '16px',
                  paddingRight: '16px',
                  paddingTop: '12px',
                  paddingBottom: '12px',
                  minHeight: '48px',
                  color: '#0b2d2c',
                  transition: 'all 0.2s ease',
                  '&:hover': {
                    backgroundColor: '#f5f5f5',
                  },
                  '&:focus': {
                    outline: '2px solid #0b2d2c',
                    outlineOffset: '-2px',
                  },
                }}
              >
                <ListItemIcon
                  sx={{
                    minWidth: '40px',
                    display: 'flex',
                    justifyContent: 'center',
                  }}
                >
                  {item.icon}
                </ListItemIcon>
                <ListItemText
                  primary={item.label}
                  primaryTypographyProps={{
                    fontSize: '15px',
                    fontWeight: 500,
                    color: '#0b2d2c',
                  }}
                />
              </ListItemButton>
            </ListItem>
          ))}

          {/* Theme Selector Section */}
          <Box
            sx={{
              padding: '16px',
              borderTop: '1px solid #e0e0e0',
              borderBottom: '1px solid #e0e0e0',
              marginTop: 'auto',
            }}
          >
            <FormControl fullWidth size="small">
              <InputLabel id="theme-select-label" sx={{ fontSize: '14px', color: '#0b2d2c' }}>
                Theme
              </InputLabel>
              <Select
                labelId="theme-select-label"
                id="theme-select"
                value={currentTheme}
                label="Theme"
                onChange={handleThemeChange}
                aria-label="Select theme"
                sx={{
                  fontSize: '14px',
                  '& .MuiOutlinedInput-notchedOutline': {
                    borderColor: '#e0e0e0',
                  },
                  '&:hover .MuiOutlinedInput-notchedOutline': {
                    borderColor: '#0b2d2c',
                  },
                  '&.Mui-focused .MuiOutlinedInput-notchedOutline': {
                    borderColor: '#0b2d2c',
                  },
                }}
              >
                <MenuItem value="theme-a">
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <Box
                      sx={{
                        width: '16px',
                        height: '16px',
                        borderRadius: '50%',
                        background: 'linear-gradient(135deg, #0b2d2c 50%, #fff0de 50%)',
                        border: '1px solid #e0e0e0',
                      }}
                    />
                    <Typography fontSize="14px">Theme A (Warm Teal)</Typography>
                  </Box>
                </MenuItem>
                <MenuItem value="theme-b">
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <Box
                      sx={{
                        width: '16px',
                        height: '16px',
                        borderRadius: '50%',
                        background: 'linear-gradient(135deg, #022e35 50%, #cdecf5 50%)',
                        border: '1px solid #e0e0e0',
                      }}
                    />
                    <Typography fontSize="14px">Theme B (Cool Cyan)</Typography>
                  </Box>
                </MenuItem>
              </Select>
            </FormControl>
          </Box>
        </List>

        {/* Sticky Bottom Section */}
        <Box
          sx={{
            padding: '16px',
            borderTop: '1px solid #e0e0e0',
            display: 'flex',
            flexDirection: 'column',
            gap: '8px',
          }}
        >
          {bottomMenuItems.map((item) => (
            <ListItemButton
              key={item.id}
              onClick={item.action}
              aria-label={item.label}
              sx={{
                paddingLeft: '16px',
                paddingRight: '16px',
                paddingTop: '10px',
                paddingBottom: '10px',
                minHeight: '40px',
                color: item.isDanger ? '#d32f2f' : '#0b2d2c',
                borderRadius: '4px',
                transition: 'all 0.2s ease',
                '&:hover': {
                  backgroundColor: item.isDanger ? 'rgba(211, 47, 47, 0.08)' : '#f5f5f5',
                },
                '&:focus': {
                  outline: '2px solid #0b2d2c',
                  outlineOffset: '-2px',
                },
              }}
            >
              <ListItemIcon
                sx={{
                  minWidth: '40px',
                  display: 'flex',
                  justifyContent: 'center',
                }}
              >
                {item.icon}
              </ListItemIcon>
              <ListItemText
                primary={item.label}
                primaryTypographyProps={{
                  fontSize: '14px',
                  fontWeight: 500,
                  color: item.isDanger ? '#d32f2f' : '#0b2d2c',
                }}
              />
            </ListItemButton>
          ))}

          {/* Version Code */}
          <Box
            sx={{
              marginTop: '12px',
              paddingTop: '12px',
              borderTop: '1px solid #e0e0e0',
              textAlign: 'center',
            }}
          >
            <Typography
              variant="caption"
              sx={{
                fontSize: '12px',
                fontWeight: 400,
                color: '#999999',
              }}
            >
              {versionCode}
            </Typography>
          </Box>
        </Box>
      </Box>
    </Drawer>
  );
};

export default UserProfilePanel;
